  1	import { useCallback, useLayoutEffect, useRef, useState } from "react";
  2	import { captureChatOwnership } from "@/store/chat";
  3	import type { OutgoingMediaPreview } from "@/store/outgoingMediaPreviews";
  4	import { useMotionOK } from "@/lib/motion";
  5	import { useTranslation } from "react-i18next";
  6	import { useFileStatus } from "@/store/fileAvailability";
  7	import { useFileObjectUrl } from "./mediaFile";
  8	import { ReceiveProgress } from "./ReceiveProgress";
  9	import { stickerSummary } from "@/lib/stickerMedia";
 10	
 11	/** Artwork belongs to the received manifest, independently of installed packs. */
 12	export function MediaSticker({
 13	  fileConv,
 14	  mime,
 15	  fallback,
 16	  label,
 17	  readOnly = false,
 18	  localPreview,
 19	}: {
 20	  fileConv: string;
 21	  mime: string;
 22	  fallback: string;
 23	  label?: string;
 24	  readOnly?: boolean;
 25	  localPreview?: OutgoingMediaPreview;
 26	}) {
 27	  const { t } = useTranslation();
 28	  const motionOK = useMotionOK();
 29	  const description = stickerSummary({ label }, t("message.sticker"));
 30	  const status = useFileStatus(fileConv || undefined);
 31	  const [readFailed, setReadFailed] = useState(false);
 32	  const [retryKey, setRetryKey] = useState(0);
 33	  const onReadError = useCallback(() => setReadFailed(true), []);
 34	  const url = useFileObjectUrl(
 35	    fileConv,
 36	    !!status?.ready && !status.unavailable,
 37	    mime,
 38	    { onReadError, retryKey, reuse: true },
 39	  );
 40	  const [failedUrl, setFailedUrl] = useState<string | null>(null);
 41	  const [decodedUrl, setDecodedUrl] = useState<string | null>(null);
 42	  const source = useRef<{ fileConv: string; url: string | null } | null>(null);
 43	  useLayoutEffect(() => {
 44	    source.current = { fileConv, url };
 45	    return () => {
 46	      source.current = null;
 47	    };
 48	  }, [fileConv, url]);
 49	  const lease = captureChatOwnership();
 50	  const currentImage = (image: HTMLImageElement) =>
 51	    lease.current() &&
 52	    source.current?.fileConv === fileConv &&
 53	    source.current.url === url &&
 54	    image.getAttribute("src") === url;
 55	  const [failedPreview, setFailedPreview] = useState<string | null>(null);
 56	  const preview =
 57	    !readOnly && localPreview?.current() && failedPreview !== localPreview.url
 58	      ? localPreview
 59	      : undefined;
 60	  const durable = !!url && failedUrl !== url;
 61	  const decoded = durable && decodedUrl === url;
 62	  return (
 63	    <div className="w-32 max-w-full space-y-2 text-center">
 64	      <div className="relative h-32 w-32 max-w-full">
 65	        {preview && !decoded ? (
 66	          <img
 67	            data-testid="outgoing-media-preview"
 68	            key={preview.url}
 69	            src={preview.url}
 70	            onError={() => {
 71	              if (preview.current() && lease.current())
 72	                setFailedPreview(preview.url);
 73	            }}
 74	            alt={description}
 75	            title={label}
 76	            draggable={false}
 77	            className="absolute inset-0 h-32 w-32 max-w-full select-none object-contain"
 78	          />
 79	        ) : !preview ? (
 80	          <span
 81	            data-testid="message-sticker-fallback"
 82	            aria-hidden={decoded}
 83	            style={{
 84	              opacity: decoded ? 0 : 1,
 85	              transition: `opacity ${motionOK ? 180 : 80}ms cubic-bezier(0.22, 1, 0.36, 1)`,
 86	            }}
 87	            role="img"
 88	            aria-label={description}
 89	            className="inline-flex h-32 w-32 max-w-full items-center justify-center text-6xl"
 90	          >
 91	            {fallback}
 92	          </span>
 93	        ) : null}
 94	        {durable && (
 95	          <img
 96	            key={url}
 97	            src={url}
 98	            alt={description}
 99	            title={label}
100	            aria-hidden={!decoded}
101	            data-testid="message-sticker"
102	            draggable={false}
103	            onLoad={(event) => {
104	              if (
105	                !currentImage(event.currentTarget) ||
106	                !event.currentTarget.naturalWidth ||
107	                !event.currentTarget.naturalHeight
108	              )
109	                return;
110	              setDecodedUrl(url);
111	              if (preview?.current()) preview.release();
112	            }}
113	            onError={(event) => {
114	              if (currentImage(event.currentTarget)) setFailedUrl(url);
115	            }}
116	            className="absolute inset-0 h-32 w-32 max-w-full select-none object-contain"
117	            style={{
118	              opacity: decoded ? 1 : 0,
119	            }}
120	          />
121	        )}
122	      </div>
123	      {(failedUrl && url) ||
124	      (readFailed && status?.ready && !status.unavailable) ? (
125	        <div className="text-xs text-muted-foreground">
126	          <p role="status">
127	            {t(url ? "files.imageUnsupported" : "files.unavailable")}
128	          </p>
129	          {!readOnly && (
130	            <button
131	              type="button"
132	              onClick={() => {
133	                setFailedUrl(null);
134	                setReadFailed(false);
135	                setRetryKey((key) => key + 1);
136	              }}
137	              className="mt-1 rounded-md border px-2 py-1 hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
138	            >
139	              {t("common.retry")}
140	            </button>
141	          )}
142	        </div>
143	      ) : decoded || preview ? null : status?.ready ? (
144	        <p role="status" className="text-xs text-muted-foreground">
145	          {t("common.loading")}
146	        </p>
147	      ) : (
148	        <ReceiveProgress status={status} />
149	      )}
150	    </div>
151	  );
152	}
