  1	//! Device-local expiry for discovered accounts that never had durable history.
  2	use super::*;
  3	
  4	use crate::chat_commands::AccountInfo;
  5	use std::{collections::BTreeMap, io::Read};
  6	
  7	const EMPTY_CONTACT_LIFETIME_MS: u64 = 86_400_000;
  8	const MAX_EXPIRY_CONTACTS: usize = 4096;
  9	const MAX_EXPIRY_BYTES: u64 = 512 * 1024;
 10	
 11	#[derive(Default, Serialize, Deserialize)]
 12	#[serde(deny_unknown_fields)]
 13	struct FirstObservations {
 14	    contacts: BTreeMap<String, ObservedContact>,
 15	}
 16	
 17	#[derive(Serialize, Deserialize)]
 18	#[serde(deny_unknown_fields)]
 19	struct ObservedContact {
 20	    first_seen_ms: u64,
 21	    ever_history: bool,
 22	}
 23	
 24	impl HiddenContactsState {
 25	    fn expiry_path(&self, owner: &str, own_account: &str) -> PathBuf {
 26	        self.root
 27	            .join("accounts")
 28	            .join(owner)
 29	            .join(format!("empty-contacts-{own_account}.json"))
 30	    }
 31	
 32	    /// Caller owns the existing policy/session transaction. No lock is acquired
 33	    /// here: expiry must compose with explicit visibility without reversing order.
 34	    pub(crate) fn expire_empty_accounts(
 35	        &self,
 36	        owner: &str,
 37	        own_account: &str,
 38	        rows: &mut Vec<AccountInfo>,
 39	        ever_history: &HashSet<String>,
 40	        now_ms: u64,
 41	    ) -> Result<(), String> {
 42	        authorize(Some(owner), owner)?;
 43	        if !valid_account(own_account) {
 44	            return Err("Invalid expiry account".into());
 45	        }
 46	        if rows.is_empty() {
 47	            return Ok(());
 48	        }
 49	        let path = self.expiry_path(owner, own_account);
 50	        let mut journal = match std::fs::File::open(&path) {
 51	            Ok(file) => {
 52	                let mut bytes = Vec::new();
 53	                file.take(MAX_EXPIRY_BYTES + 1)
 54	                    .read_to_end(&mut bytes)
 55	                    .map_err(|e| e.to_string())?;
 56	                if bytes.len() as u64 > MAX_EXPIRY_BYTES {
 57	                    return Err("Contact expiry journal too large".into());
 58	                }
 59	                serde_json::from_slice::<FirstObservations>(&bytes).map_err(|e| e.to_string())?
 60	            }
 61	            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
 62	                FirstObservations::default()
 63	            }
 64	            Err(error) => return Err(error.to_string()),
 65	        };
 66	        if journal.contacts.len() > MAX_EXPIRY_CONTACTS
 67	            || journal.contacts.keys().any(|id| !valid_account(id))
 68	        {
 69	            return Err("Invalid contact expiry journal".into());
 70	        }
 71	        let mut changed = false;
 72	        for row in rows.iter() {
 73	            if row.account_id == own_account || !valid_account(&row.account_id) {
 74	                continue;
 75	            }
 76	            let history = ever_history.contains(&row.account_id);
 77	            if let Some(observed) = journal.contacts.get_mut(&row.account_id) {
 78	                if history && !observed.ever_history {
 79	                    observed.ever_history = true;
 80	                    changed = true;
 81	                }
 82	            } else if journal.contacts.len() < MAX_EXPIRY_CONTACTS {
 83	                journal.contacts.insert(
 84	                    row.account_id.clone(),
 85	                    ObservedContact {
 86	                        first_seen_ms: now_ms,
 87	                        ever_history: history,
 88	                    },
 89	                );
 90	                changed = true;
 91	            }
 92	        }
 93	        if changed {
 94	            let parent = path.parent().ok_or("Invalid expiry journal path")?;
 95	            std::fs::create_dir_all(parent).map_err(|e| e.to_string())?;
 96	            let mut temporary =
 97	                tempfile::NamedTempFile::new_in(parent).map_err(|e| e.to_string())?;
 98	            #[cfg(unix)]
 99	            {
100	                use std::os::unix::fs::PermissionsExt;
101	                temporary
102	                    .as_file()
103	                    .set_permissions(std::fs::Permissions::from_mode(0o600))
104	                    .map_err(|e| e.to_string())?;
105	            }
106	            serde_json::to_writer(&mut temporary, &journal).map_err(|e| e.to_string())?;
107	            temporary.flush().map_err(|e| e.to_string())?;
108	            temporary.as_file().sync_all().map_err(|e| e.to_string())?;
109	            temporary.persist(&path).map_err(|e| e.to_string())?;
110	            #[cfg(unix)]
111	            if std::fs::File::open(parent)
112	                .and_then(|directory| directory.sync_all())
113	                .is_err()
114	            {
115	                log::warn!("Contact expiry committed; directory durability sync unavailable");
116	            }
117	        }
118	        // Persist before publishing any deadline or omission. Retain expired keys
119	        // so continuous discovery cannot recreate them. Saturation fails open for
120	        // new accounts; keys are not evicted because that would renew old clocks.
121	        rows.retain_mut(|row| {
122	            row.contact_expires_at_ms =
123	                if row.account_id == own_account || ever_history.contains(&row.account_id) {
124	                    None
125	                } else {
126	                    journal
127	                        .contacts
128	                        .get(&row.account_id)
129	                        .filter(|observed| !observed.ever_history)
130	                        .map(|observed| {
131	                            observed
132	                                .first_seen_ms
133	                                .saturating_add(EMPTY_CONTACT_LIFETIME_MS)
134	                        })
135	                };
136	            row.contact_expires_at_ms
137	                .is_none_or(|deadline| now_ms < deadline)
138	        });
139	        Ok(())
140	    }
141	}
