+        reads
+    );
+    sent.remove_where(|_| true).unwrap();
+    received.remove_where(|_| true).unwrap();
+    files.remove_where(|_| true).unwrap();
+    drop((sent, received, files));
+    drop(owner);
+    let owner = profile(dir.path(), &identity, &account);
